{{/* templates/_helpers.tpl */}}
{{- define "shop.labels" -}}
app.kubernetes.io/name: {{ .Chart.Name }}
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
{{- end }}

{{/* templates/configmap.yaml */}}
apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ .Release.Name }}-env
  labels:
    {{- include "shop.labels" . | nindent 4 }}
data:
  {{- range $key, $val := .Values.env }}
  {{ $key }}: {{ $val | quote }}
  {{- end }}
  {{- with .Values.extraConfig }}
  extra.conf: {{ . | quote }}
  {{- end }}

{{/* Keep a generated password stable across upgrades */}}
{{- $existing := lookup "v1" "Secret" .Release.Namespace (printf "%s-db" .Release.Name) }}
{{- $pw := "" }}
{{- if $existing }}
{{-   $pw = index $existing.data "password" | b64dec }}
{{- else }}
{{-   $pw = randAlphaNum 24 }}
{{- end }}
apiVersion: v1
kind: Secret
metadata:
  name: {{ .Release.Name }}-db
  annotations:
    {{- tpl (toYaml .Values.extraAnnotations) . | nindent 4 }}
stringData:
  password: {{ $pw | quote }}
{{- if and .Values.ingress.enabled (not .Values.ingress.hosts) }}
{{-   fail "ingress.enabled requires at least one ingress.hosts entry" }}
{{- end }}
